# Restore Microsoft Teams (Consumer) Settings Write-Host "Restoring Microsoft Teams settings..." -ForegroundColor Cyan # Re-enable chat icon on taskbar Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarMn" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent" -Name "DisableConsumerTeams" -ErrorAction SilentlyContinue Write-Host "Teams settings restored." -ForegroundColor Green Write-Host "Note: The Teams app was removed and needs to be reinstalled from Microsoft Store." -ForegroundColor Yellow